/**
 * Milestone invariants that are neither a permission nor a tenant-scope
 * concern: a closed milestone refusing further state changes, the
 * open-milestone cap and name collisions.
 */

export type MilestoneStateReason =
  | "closed"
  | "already_open"
  | "too_many_open"
  | "name_taken";

export class MilestoneStateError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly reason: MilestoneStateReason,
    message: string,
  ) {
    super(message);
    this.name = "MilestoneStateError";
  }
}

/** Case- and whitespace-insensitive name comparison within a project. */
export function normalizeMilestoneName(name: string): string {
  return name.trim().toLowerCase();
}

