export async function setIssueMilestone(
  orgId: OrgId,
  issueId: IssueId,
  milestoneId: MilestoneId | null,
): Promise<Issue> {
  const row = getDb()
    .update(issues)
    .set({ milestoneId, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning()
    .get();

  if (!row) throw new Error(`Issue ${issueId} not found`);
  return toIssue(row);
}

/** Live issues in an open status currently parked in `milestoneId`. */
export async function listOpenLiveIssuesInMilestone(
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        eq(issues.milestoneId, milestoneId),
        isNull(issues.archivedAt),
        not(inArray(issues.status, [...CLOSED_ISSUE_STATUSES])),
      ),
    )
    .all();

  return rows.map((row) => toIssue(row));
}

/** Bulk re-point of a set of issues onto another milestone (or none). */
export async function reassignMilestoneForIssues(
  orgId: OrgId,
  issueIds: readonly IssueId[],
  milestoneId: MilestoneId | null,
): Promise<void> {
  if (issueIds.length === 0) return;

  getDb()
    .update(issues)
    .set({ milestoneId, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(orgPredicate(issues.orgId, orgId), inArray(issues.id, [...issueIds])),
    )
    .run();
}

/** Live, still-open issues whose due date has passed. Drives the overdue job. */

