/**
 * Milestone rows: per-project listing, the open-milestone count behind the
 * cap, name-collision checks and live-issue progress counts.
 *
 * Must call (do not reimplement): toIsoTimestamp, normalizeMilestoneName
 */
import { and, count, eq, inArray, isNull, isNotNull } from "drizzle-orm";
import { normalizeMilestoneName } from "@/lib/milestones";
import { getDb, issues, milestones } from "@/server/db";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toMilestone } from "./_mappers";
import type { CreateMilestoneInput } from "@/schemas/milestone";
import type { IsoTimestamp, MilestoneId, OrgId, ProjectId } from "@/types/common";
import type { Milestone, MilestoneProgress } from "@/types/milestone";

export async function findMilestoneById(
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone | null> {
  const row = getDb()
    .select()
    .from(milestones)
    .where(
      and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
    )
    .get();
  return row ? toMilestone(row) : null;
}

export async function listMilestonesForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly Milestone[]> {
  const rows = getDb()
    .select()
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.projectId, projectId),
      ),
    )
    .all();
  return rows.map(toMilestone);
}

export async function countOpenMilestones(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.projectId, projectId),
        isNull(milestones.closedAt),
      ),
    )
    .get();
  return row?.value ?? 0;
}

/**
 * Names are unique within a project regardless of case or surrounding
 * whitespace, closed milestones included — so this scans every milestone of
 * the project rather than filtering in SQL.
 */
export async function isMilestoneNameTaken(
  orgId: OrgId,
  projectId: ProjectId,
  name: string,
  excludeId?: MilestoneId,
): Promise<boolean> {
  const normalized = normalizeMilestoneName(name);
  const rows = await listMilestonesForProject(orgId, projectId);
  return rows.some(
    (row) => row.id !== excludeId && normalizeMilestoneName(row.name) === normalized,
  );
}

export async function insertMilestone(
  id: string,
  input: CreateMilestoneInput,
): Promise<Milestone> {
  const stamp = toIsoTimestamp(new Date());

  const row = getDb()
    .insert(milestones)
    .values({
      id,
      orgId: input.orgId,
      projectId: input.projectId,
      name: input.name,
      targetDate: input.targetDate,
      closedAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toMilestone(row);
}

export async function updateMilestone(
  orgId: OrgId,
  milestoneId: MilestoneId,
  patch: { name?: string; targetDate?: IsoTimestamp | null },
): Promise<Milestone> {
  const row = getDb()
    .update(milestones)
    .set({
      ...(patch.name === undefined ? {} : { name: patch.name }),
      ...(patch.targetDate === undefined ? {} : { targetDate: patch.targetDate }),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Milestone ${milestoneId} not found`);
  return toMilestone(row);
}

export async function setMilestoneClosedAt(
  orgId: OrgId,
  milestoneId: MilestoneId,
  closedAt: IsoTimestamp | null,
): Promise<Milestone> {
  const row = getDb()
    .update(milestones)
    .set({ closedAt, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Milestone ${milestoneId} not found`);
  return toMilestone(row);
}

/** Total/open/closed counts over the milestone's live (non-archived) issues. */
export async function getMilestoneProgress(
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<MilestoneProgress> {
  const db = getDb();
  const scope = and(
    orgPredicate(issues.orgId, orgId),
    eq(issues.milestoneId, milestoneId),
    isNull(issues.archivedAt),
  );

  const totalRow = db.select({ value: count() }).from(issues).where(scope).get();
  const closedRow = db
    .select({ value: count() })
    .from(issues)
    .where(and(scope, inArray(issues.status, [...CLOSED_ISSUE_STATUSES])))
    .get();

  const total = totalRow?.value ?? 0;
  const closed = closedRow?.value ?? 0;

  return { total, open: total - closed, closed };
}

