/**
 * Milestone lifecycle: creation under the open-milestone cap, rename/retarget,
 * closing (which relocates the milestone's open live issues) and reopening.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, assertNotArchived, emit
 */
import { MAX_OPEN_MILESTONES_PER_PROJECT } from "@/config/constants";
import { emit } from "@/lib/event-bus";
import { newId } from "@/lib/id";
import { MilestoneStateError } from "@/lib/milestones";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as milestoneRepo from "@/server/repositories/milestone-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import {
  actorEnvelope,
  projectResource,
  requireFound,
} from "./_support";
import type {
  CloseMilestoneInput,
  CreateMilestoneInput,
  UpdateMilestoneInput,
} from "@/schemas/milestone";
import type { IssueId, MilestoneId, OrgId, ProjectId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { Milestone, MilestoneProgress, MilestoneWithProgress } from "@/types/milestone";

async function loadProjectForMilestone(
  orgId: OrgId,
  projectId: ProjectId,
): ReturnType<typeof projectRepo.findProjectById> extends Promise<infer T>
  ? Promise<NonNullable<T>>
  : never {
  return requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  ) as never;
}

async function loadMilestone(
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  return requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
}

export async function createMilestone(
  actor: Actor,
  input: CreateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);

  const project = await loadProjectForMilestone(input.orgId, input.projectId);
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  if (
    await milestoneRepo.isMilestoneNameTaken(input.orgId, input.projectId, input.name)
  ) {
    throw new MilestoneStateError(
      "name_taken",
      `A milestone named "${input.name}" already exists in this project`,
    );
  }

  const openCount = await milestoneRepo.countOpenMilestones(
    input.orgId,
    input.projectId,
  );
  if (openCount >= MAX_OPEN_MILESTONES_PER_PROJECT) {
    throw new MilestoneStateError(
      "too_many_open",
      `Project already has ${openCount} open milestones; close one before adding another`,
    );
  }

  const milestone = await milestoneRepo.insertMilestone(newId(), input);

  await emit("milestone.created", {
    ...actorEnvelope(actor),
    milestoneId: milestone.id,
    projectId: milestone.projectId,
  });

  return milestone;
}

export async function updateMilestone(
  actor: Actor,
  input: UpdateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);

  const milestone = await loadMilestone(input.orgId, input.milestoneId);
  const project = await loadProjectForMilestone(input.orgId, milestone.projectId);
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  if (
    input.name !== undefined &&
    (await milestoneRepo.isMilestoneNameTaken(
      input.orgId,
      milestone.projectId,
      input.name,
      milestone.id,
    ))
  ) {
    throw new MilestoneStateError(
      "name_taken",
      `A milestone named "${input.name}" already exists in this project`,
    );
  }

  return milestoneRepo.updateMilestone(input.orgId, input.milestoneId, {
    name: input.name,
    targetDate: input.targetDate,
  });
}

export async function closeMilestone(
  actor: Actor,
  input: CloseMilestoneInput,
): Promise<{ milestone: Milestone; movedIssueIds: readonly IssueId[] }> {
  assertOrgScope(actor, input.orgId);

  const milestone = await loadMilestone(input.orgId, input.milestoneId);
  const project = await loadProjectForMilestone(input.orgId, milestone.projectId);
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  if (milestone.closedAt !== null) {
    throw new MilestoneStateError(
      "closed",
      `Milestone ${milestone.id} is already closed`,
    );
  }

  let moveTarget: Milestone | null = null;
  if (input.moveOpenIssuesTo !== null) {
    if (input.moveOpenIssuesTo === milestone.id) {
      throw requireFound(null, "Milestone", input.moveOpenIssuesTo);
    }

    moveTarget = requireFound(
      await milestoneRepo.findMilestoneById(input.orgId, input.moveOpenIssuesTo),
      "Milestone",
      input.moveOpenIssuesTo,
    );

    if (moveTarget.projectId !== milestone.projectId) {
      throw requireFound(null, "Milestone", input.moveOpenIssuesTo);
    }

    if (moveTarget.closedAt !== null) {
      throw new MilestoneStateError(
        "closed",
        `Milestone ${moveTarget.id} is closed`,
      );
    }
  }

  const openIssues = await issueRepo.listOpenLiveIssuesInMilestone(
    input.orgId,
    milestone.id,
  );
  const movedIssueIds = openIssues.map((issue) => issue.id);

  await issueRepo.reassignMilestoneForIssues(
    input.orgId,
    movedIssueIds,
    moveTarget?.id ?? null,
  );

  const closed = await milestoneRepo.setMilestoneClosedAt(
    input.orgId,
    milestone.id,
    actorEnvelope(actor).occurredAt,
  );

  await emit("milestone.closed", {
    ...actorEnvelope(actor),
    milestoneId: closed.id,
    projectId: closed.projectId,
    movedToMilestoneId: moveTarget?.id ?? null,
    movedIssueIds,
  });

  return { milestone: closed, movedIssueIds };
}

export async function reopenMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  assertOrgScope(actor, orgId);

  const milestone = await loadMilestone(orgId, milestoneId);
  const project = await loadProjectForMilestone(orgId, milestone.projectId);
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  if (milestone.closedAt === null) {
    throw new MilestoneStateError(
      "already_open",
      `Milestone ${milestone.id} is already open`,
    );
