      expect(result.movedIssueIds).toEqual([issue.id]);
      expect(received).toHaveLength(1);
    } finally {
      off();
    }

    const movedIssue = await issueService.getIssue(tenant.actors.member, tenant.org.id, issue.id);
    expect(movedIssue.issue.milestoneId).toBe(m3.id);

    const notifications = await notificationRepo.listNotifications({
      orgId: tenant.org.id,
      recipientId: tenant.userIds.member,
      unreadOnly: false,
      limit: 25,
      cursor: null,
    });
    expect(
      notifications.items.some((n) => n.kind === "issue_milestone_changed"),
    ).toBe(true);

    // reopening an open milestone is refused
    await expect(
      milestoneService.reopenMilestone(tenant.actors.admin, tenant.org.id, m3.id),
    ).rejects.toBeInstanceOf(MilestoneStateError);

    const reopened = await milestoneService.reopenMilestone(
      tenant.actors.admin,
      tenant.org.id,
      m1.id,
    );
    expect(reopened.closedAt).toBeNull();

    // moving into another project's milestone -> NotFoundError
    const otherTenant = await createTenant("msmoke2", "growth");
    const foreignMilestone = await milestoneService.createMilestone(
      otherTenant.actors.member,
      {
        orgId: otherTenant.org.id,
        projectId: otherTenant.project.id,
        name: "Foreign",
        targetDate: null,
      },
    );
    await expect(
      issueService.setIssueMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        milestoneId: foreignMilestone.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("enforces the open-milestone cap", async () => {
    const tenant = await createTenant("mcap", "growth");
    for (let i = 0; i < MAX_OPEN_MILESTONES_PER_PROJECT; i += 1) {
      await milestoneService.createMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        name: `M${i}`,
        targetDate: null,
      });
    }
    await expect(
      milestoneService.createMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        name: "Overflow",
        targetDate: null,
      }),
