import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { subscribe } from "@/lib/event-bus";
import { MilestoneStateError } from "@/lib/milestones";
import { NotFoundError } from "@/server/services/_support";
import * as issueService from "@/server/services/issue-service";
import * as milestoneService from "@/server/services/milestone-service";
import * as notificationRepo from "@/server/repositories/notification-repository";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import { MAX_OPEN_MILESTONES_PER_PROJECT } from "@/config/constants";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

describe("milestone smoke", () => {
  it("creates, lists in order, closes with move, reopens, and enforces cap/name rules", async () => {
    const tenant = await createTenant("msmoke", "growth");

    const m1 = await milestoneService.createMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      name: "Alpha",
      targetDate: null,
    });

    // case/whitespace-insensitive name collision
    await expect(
      milestoneService.createMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        name: "  alpha ",
        targetDate: null,
      }),
    ).rejects.toBeInstanceOf(MilestoneStateError);

    const m2 = await milestoneService.createMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      name: "Beta",
      targetDate: "2020-01-01T00:00:00.000Z" as never,
    });

    const listed = await milestoneService.listMilestones(
      tenant.actors.viewer,
      tenant.org.id,
      tenant.project.id,
    );
    // Beta has a target date, Alpha doesn't -> Beta first among open ones.
    expect(listed.map((x) => x.milestone.name)).toEqual(["Beta", "Alpha"]);

    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Needs a milestone",
        assigneeId: tenant.userIds.member,
      }),
    );

    const withMilestone = await issueService.setIssueMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      milestoneId: m1.id,
    });
    expect(withMilestone.milestoneId).toBe(m1.id);

    // closing into a closed milestone target is refused
    await milestoneService.closeMilestone(tenant.actors.admin, {
      orgId: tenant.org.id,
      milestoneId: m2.id,
      moveOpenIssuesTo: null,
    });
    await expect(
      milestoneService.closeMilestone(tenant.actors.admin, {
        orgId: tenant.org.id,
        milestoneId: m1.id,
        moveOpenIssuesTo: m2.id,
      }),
    ).rejects.toBeInstanceOf(MilestoneStateError);

    const received: unknown[] = [];
    const off = subscribe("milestone.closed", (p) => received.push(p));

    const m3 = await milestoneService.createMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      name: "Gamma",
      targetDate: null,
    });

    try {
      const result = await milestoneService.closeMilestone(tenant.actors.admin, {
        orgId: tenant.org.id,
        milestoneId: m1.id,
        moveOpenIssuesTo: m3.id,
      });
      expect(result.movedIssueIds).toEqual([issue.id]);
      expect(received).toHaveLength(1);
    } finally {
      off();
    }

    const movedIssue = await issueService.getIssue(tenant.actors.member, tenant.org.id, issue.id);
    expect(movedIssue.issue.milestoneId).toBe(m3.id);

    const notifications = await notificationRepo.listNotifications({
      orgId: tenant.org.id,
      recipientId: tenant.userIds.member,
      unreadOnly: false,
      limit: 25,
      cursor: null,
    });
    expect(
      notifications.items.some((n) => n.kind === "issue_milestone_changed"),
    ).toBe(true);

    // reopening an open milestone is refused
    await expect(
      milestoneService.reopenMilestone(tenant.actors.admin, tenant.org.id, m3.id),
    ).rejects.toBeInstanceOf(MilestoneStateError);

    const reopened = await milestoneService.reopenMilestone(
      tenant.actors.admin,
      tenant.org.id,
      m1.id,
    );
    expect(reopened.closedAt).toBeNull();

    // moving into another project's milestone -> NotFoundError
    const otherTenant = await createTenant("msmoke2", "growth");
    const foreignMilestone = await milestoneService.createMilestone(
      otherTenant.actors.member,
      {
        orgId: otherTenant.org.id,
        projectId: otherTenant.project.id,
        name: "Foreign",
        targetDate: null,
      },
    );
    await expect(
      issueService.setIssueMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        milestoneId: foreignMilestone.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("enforces the open-milestone cap", async () => {
    const tenant = await createTenant("mcap", "growth");
    for (let i = 0; i < MAX_OPEN_MILESTONES_PER_PROJECT; i += 1) {
      await milestoneService.createMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        name: `M${i}`,
        targetDate: null,
      });
    }
    await expect(
      milestoneService.createMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        name: "Overflow",
        targetDate: null,
      }),
    ).rejects.toBeInstanceOf(MilestoneStateError);
  });
});
